def hat_duplikat_langsam(liste):
    for i in range(len(liste)):
        for j in range(i + 1, len(liste)):
            if liste[i] == liste[j]:
                return True
    return False

def hat_duplikat_schnell(liste):
    gesehen = set()
    for x in liste:
        if x in gesehen:
            return True
        gesehen.add(x)
    return False

