from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(30))   # 832040
print(fib(100))
# 354224848179261915075

# Ohne Decorator, mit dict:
memo = {}
def fib2(n):
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib2(n-1) + fib2(n-2)
    return memo[n]

